const now = new Date();
const pakistanDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Karachi',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);
const [year, month, day] = pakistanDate.split('-').map(Number);
const yesterday = new Date(Date.UTC(year, month - 1, day - 1));
const y = yesterday.getUTCFullYear();
const m = String(yesterday.getUTCMonth() + 1).padStart(2, '0');
const d = String(yesterday.getUTCDate()).padStart(2, '0');

// Pakistan local time strings (for display/reporting)
const reporting_start_local = `${y}-${m}-${d}T00:00:00+05:00`;
const reporting_end_local = `${y}-${m}-${d}T23:59:59.999+05:00`;

// UTC equivalents (for APIs like Vapi that need Z format, no + sign)
const reporting_start_utc = new Date(reporting_start_local).toISOString();
const reporting_end_utc = new Date(reporting_end_local).toISOString();

return [
  {
    json: {
      report_date: `${y}-${m}-${d}`,
      reporting_start_local,
      reporting_end_local,
      reporting_start_utc,
      reporting_end_utc,
      timezone: 'Asia/Karachi'
    }
  }
];

const output = [];
for (const item of $input.all()) {
  const contacts = item.json.contacts || [];
  for (const contact of contacts) {
    output.push({
      json: {
        contact_id: contact.id || "",
