        opportunity_status: contact.opportunities?.[0]?.status || "",
        revenue: contact.opportunities?.[0]?.monetaryValue || 0,
        first_outbound_at: "" // Placeholder — depends on voice-call data merge later
      }
    });
  }
}
return output;

const output = [];
for (const item of $input.all()) {
  const opportunities = item.json.opportunities || [];
  for (const opportunity of opportunities) {
    output.push({
      json: {
        contact_id: opportunity.contactId || "",
        created_at: opportunity.createdAt || "",
        source: opportunity.source || opportunity.customFields?.[0]?.fieldValueString || "",
