const output = [];
for (const item of $input.all()) {
  const data = item.json;
  output.push({
    json: {
      contact_id: data.contact_id || null,
      created_at: data.created_at || null,
      source: data.source || null,
      appointment_status: data.appointment_status || "",
      opportunity_status: data.opportunity_status || null,
      revenue: data.revenue || 0,
      first_outbound_at: data.first_outbound_at || ""
    }
  });
}
return output;

const items = $input.all();

// safeDivide helper (doc requirement)
function safeDivide(numerator, denominator) {
  return denominator ? numerator / denominator : 0;
}
function roundPercent(val) {
  return Math.round(val * 10000) / 100; // 2 decimal places, as percentage
}

// Separate datasets based on normalized fields
const opportunityItems = items.filter(item => item.json.opportunity_status !== undefined && item.json.opportunity_status !== null);
const appointmentItems = items.filter(item => item.json.appointment_id);
const voiceCallItems = items.filter(item => item.json.call_id);
const adSpendItems = items.filter(item => item.json.ad_spend !== undefined);

// -----------------------------
// OPPORTUNITY METRICS
// -----------------------------
const uniqueLeads = new Set(opportunityItems.map(item => item.json.contact_id)).size;
const wonOpportunities = opportunityItems.filter(item => item.json.opportunity_status === 'won').length;
const lostOpportunities = opportunityItems.filter(item => item.json.opportunity_status === 'lost').length;
const qualifiedOpportunities = opportunityItems.filter(item =>
  ['open', 'won', 'lost'].includes(item.json.opportunity_status)
).length;
const wonRevenue = opportunityItems
  .filter(item => item.json.opportunity_status === 'won')
  .reduce((sum, item) => sum + Number(item.json.revenue || 0), 0);

// -----------------------------
// APPOINTMENT METRICS
// -----------------------------
const appointmentsBooked = appointmentItems.length;
const appointmentsScheduled = appointmentItems.filter(item =>
  item.json.appointment_status === 'confirmed' || item.json.appointment_status === 'scheduled'
).length;
const appointmentsShowed = appointmentItems.filter(item => item.json.appointment_status === 'showed').length;
const totalNoShows = appointmentItems.filter(item =>
  item.json.appointment_status === 'noshow' || item.json.appointment_status === 'no_show'
).length;
const rebookedNoShows = appointmentItems.filter(item => item.json.appointment_status === 'rebooked').length;

// -----------------------------
// VOICE CALL METRICS (speed to lead)
// -----------------------------
let speedToLeadSeconds = 0;
const leadWithOutbound = opportunityItems.find(item => item.json.first_outbound_at && item.json.created_at);
if (leadWithOutbound) {
  const created = new Date(leadWithOutbound.json.created_at).getTime();
  const outbound = new Date(leadWithOutbound.json.first_outbound_at).getTime();
  if (!isNaN(created) && !isNaN(outbound)) {
    speedToLeadSeconds = (outbound - created) / 1000;
  }
}

// -----------------------------
// AD-SPEND
// -----------------------------
const totalAdSpend = adSpendItems.reduce((sum, item) => sum + Number(item.json.ad_spend || 0), 0);

// -----------------------------
// REQUIRED KPIs (doc table, exact formulas)
// -----------------------------
const leadToAppointmentRate = safeDivide(appointmentsBooked, uniqueLeads);
const showRate = safeDivide(appointmentsShowed, appointmentsScheduled);
const closeRate = safeDivide(wonOpportunities, qualifiedOpportunities);
const costPerLead = safeDivide(totalAdSpend, uniqueLeads);
const costPerAppointment = safeDivide(totalAdSpend, appointmentsBooked);
const revenuePerLead = safeDivide(wonRevenue, uniqueLeads);
const noShowRecoveryRate = safeDivide(rebookedNoShows, totalNoShows);

return [
  {
    json: {
      report_date: $('Set Reporting Window').first().json.report_date,

      // Raw counts (for reference)
      unique_leads: uniqueLeads,
      won_opportunities: wonOpportunities,
      lost_opportunities: lostOpportunities,
      qualified_opportunities: qualifiedOpportunities,
      won_revenue: wonRevenue,
      appointments_booked: appointmentsBooked,
      appointments_scheduled: appointmentsScheduled,
      appointments_showed: appointmentsShowed,
      total_no_shows: totalNoShows,
      rebooked_no_shows: rebookedNoShows,
      total_ad_spend: totalAdSpend,
      speed_to_lead_seconds: speedToLeadSeconds,

      // Required KPIs (doc formulas)
      lead_to_appointment_rate: roundPercent(leadToAppointmentRate),
      show_rate: roundPercent(showRate),
      close_rate: roundPercent(closeRate),
      cost_per_lead: Math.round(costPerLead * 100) / 100,
      cost_per_appointment: Math.round(costPerAppointment * 100) / 100,
      revenue_per_lead: Math.round(revenuePerLead * 100) / 100,
      speed_to_lead_minutes: Math.round(speedToLeadSeconds / 60),
      no_show_recovery_rate: roundPercent(noShowRecoveryRate),

      generated_at: new Date().toISOString()
    }
  }
];

const metrics = $('Calculate Daily Metrics').first().json;
const anomalyData = $('Detect Anomalies').first().json;

const anomalySection = anomalyData.anomaly_detected
  ? anomalyData.anomalies.map(a => `  - ${a.issue} (Current: ${a.current}, Baseline: ${a.baseline ?? 'N/A'})`).join('\n')
  : (anomalyData.baseline_available ? '  No anomalies detected.' : '  Baseline not available yet — comparison skipped.');

const report = `
DAILY HVAC REPORT
=================
Report Date: ${metrics.report_date}

MAIN KPIs
---------
Unique Leads: ${metrics.unique_leads}
Appointments Booked: ${metrics.appointments_booked}
Lead-to-Appointment Rate: ${metrics.lead_to_appointment_rate}%
Show Rate: ${metrics.show_rate}%
Close Rate: ${metrics.close_rate}%
Cost per Lead: $${metrics.cost_per_lead}
Cost per Appointment: $${metrics.cost_per_appointment}
Revenue per Lead: $${metrics.revenue_per_lead}
Speed to Lead: ${metrics.speed_to_lead_minutes} minutes
No-Show Recovery Rate: ${metrics.no_show_recovery_rate}%
Total Ad Spend: $${metrics.total_ad_spend}

ANOMALIES
---------
${anomalySection}

DATA QUALITY
------------
Warning Count: ${anomalyData.data_quality_warning_count}

Generated At: ${metrics.generated_at}
`;

return [
  {
    json: {
      report_date: metrics.report_date,
      unique_leads: metrics.unique_leads,
      appointments_booked: metrics.appointments_booked,
      lead_to_appointment_rate: metrics.lead_to_appointment_rate,
      show_rate: metrics.show_rate,
      close_rate: metrics.close_rate,
      cost_per_lead: metrics.cost_per_lead,
      cost_per_appointment: metrics.cost_per_appointment,
      revenue_per_lead: metrics.revenue_per_lead,
      speed_to_lead_minutes: metrics.speed_to_lead_minutes,
      no_show_recovery_rate: metrics.no_show_recovery_rate,
      total_ad_spend: metrics.total_ad_spend,
      anomaly_detected: anomalyData.anomaly_detected,
      anomaly_count: anomalyData.anomaly_count || 0,
      data_quality_warning_count: anomalyData.data_quality_warning_count,
      report_text: report.trim()
    }
  }
];

const allItems = $input.all();

const output = allItems.map(item => {
  const call = item.json;
  const startedAt = call.startedAt ? new Date(call.startedAt) : null;
  const endedAt = call.endedAt ? new Date(call.endedAt) : null;
  let durationSeconds = null;
  if (startedAt && endedAt && !isNaN(startedAt) && !isNaN(endedAt)) {
    durationSeconds = Math.round((endedAt - startedAt) / 1000);
  }
  return {
    json: {
      call_id: call.id ?? null,
      assistant_id: call.assistantId ?? null,
      call_type: call.type ?? null,
      started_at: call.startedAt ?? null,
      ended_at: call.endedAt ?? null,
      duration_seconds: durationSeconds,
      status: call.status ?? null,
      ended_reason: call.endedReason ?? null,
      cost: call.cost ?? 0,
      customer_phone: call.customer?.number ?? call.phoneNumber ?? null,
      transcript: call.transcript ?? null,
      summary: call.summary ?? null,
      created_at: call.createdAt ?? null,
      updated_at: call.updatedAt ?? null
    }
  };
});

const filtered = output.filter(o => o.json.call_id !== null);
if (filtered.length === 0) {
  return [{ json: {} }];
}
return filtered;

const output = [];
for (const item of items) {
  const events = item.json.events || [];
  for (const event of events) {
    output.push({
      json: {
        appointment_id: event.id ?? null,
        contact_id: event.contactId ?? null,
        calendar_id: event.calendarId ?? null,
        location_id: event.locationId ?? null,
        appointment_status: event.appointmentStatus ?? event.appoinmentStatus ?? null,
        assigned_user_id: event.assignedUserId ?? null,
        start_time: event.startTime ?? null,
        end_time: event.endTime ?? null,
        title: event.title ?? null,
        address: event.address ?? null,
        is_recurring: event.isRecurring ?? false,
        deleted: event.deleted ?? false,
        created_at: event.dateAdded ?? null,
        updated_at: event.dateUpdated ?? null
      }
    });
  }
}

// Agar koi appointments na hon, ek empty placeholder return karo taake workflow crash na ho
if (output.length === 0) {
  return [{ json: {} }];
}

return output;

const allItems = $input.all();
const seenAppointmentIds = new Set();
const duplicateAppointmentIds = new Set();

// Pehle pass: duplicate appointment IDs dhoondo
for (const item of allItems) {
  const data = item.json;
  if (data.appointment_id) {
    if (seenAppointmentIds.has(data.appointment_id)) {
      duplicateAppointmentIds.add(data.appointment_id);
    }
    seenAppointmentIds.add(data.appointment_id);
  }
}

const validOpportunityStatuses = ['open', 'won', 'lost', 'abandoned'];
let totalWarningCount = 0;

const output = allItems.map(item => {
  const data = item.json;
  const errors = [];
  let recordType = 'unknown';

  // Helper: valid timestamp check
  const isValidTimestamp = (val) => {
    if (!val) return false;
    const d = new Date(val);
    return !isNaN(d.getTime());
  };

  // -----------------------------
  // OPPORTUNITY RECORD
  // -----------------------------
  if (data.opportunity_id || (data.hasOwnProperty('opportunity_status') && data.opportunity_status)) {
    recordType = 'opportunity';
    if (!data.contact_id) errors.push('Missing contact_id');
    if (data.created_at && !isValidTimestamp(data.created_at)) errors.push('Invalid created_at timestamp');
    if (typeof data.revenue === 'number' && data.revenue < 0) errors.push('Negative revenue');
    if (data.opportunity_status && !validOpportunityStatuses.includes(data.opportunity_status)) {
      errors.push('Unknown opportunity status');
    }
  }
  // -----------------------------
  // APPOINTMENT RECORD
  // -----------------------------
  else if (data.appointment_id) {
    recordType = 'appointment';
    if (!data.contact_id) errors.push('Missing contact_id');
    if (data.start_time && !isValidTimestamp(data.start_time)) errors.push('Invalid start_time timestamp');
    if (data.end_time && !isValidTimestamp(data.end_time)) errors.push('Invalid end_time timestamp');
    if (!data.appointment_status) errors.push('Missing appointment status');
    if (duplicateAppointmentIds.has(data.appointment_id)) errors.push('Duplicate appointment_id');
  }
  // -----------------------------
  // VOICE CALL RECORD
  // -----------------------------
  else if (data.call_id) {
    recordType = 'voice_call';
    if (data.started_at && !isValidTimestamp(data.started_at)) errors.push('Invalid started_at timestamp');
    if (!data.status) errors.push('Missing call status');
    if (data.duration_seconds !== undefined && Number.isNaN(Number(data.duration_seconds))) {
      errors.push('Invalid duration_seconds');
    }
    if (data.cost !== undefined && Number.isNaN(Number(data.cost))) {
      errors.push('Invalid call cost');
    }
  }
  // -----------------------------
  // AD-SPEND RECORD
  // -----------------------------
  else if (data.ad_spend !== undefined) {
    recordType = 'ad_spend';
    if (!data.campaign_id) errors.push('Ad spend with no matching campaign identifier');
    if (typeof data.ad_spend === 'number' && data.ad_spend < 0) errors.push('Negative ad spend');
  }
  // -----------------------------
  // EMPTY/UNKNOWN RECORD
  // -----------------------------
  else if (Object.keys(data).length === 0) {
    recordType = 'empty';
  }
  else {
    errors.push('Unknown record type');
  }

  totalWarningCount += errors.length;

  return {
    json: {
      ...data,
      data_quality: {
        record_type: recordType,
        status: errors.length === 0 ? 'valid' : 'invalid',
        error_count: errors.length,
        errors: errors
      }
    }
  };
});

// Total warning count ko har item mein add karo (report ke liye globally accessible)
return output.map(item => ({
  json: {
    ...item.json,
    data_quality_warning_count: totalWarningCount
  }
}));

const baseline = $input.first().json;
const current = $('Calculate Daily Metrics').first().json;
const dataQuality = $('Validate Data Quality').first().json;
const warningCount = dataQuality.data_quality_warning_count || 0;

if (!baseline.baseline_available) {
  return [
    {
      json: {
        report_date: current.report_date,
        baseline_available: false,
        anomaly_detected: false,
        anomaly_status: 'baseline_not_available',
        message: 'No previous historical reports are available yet. Anomaly detection will begin once historical data exists.',
        anomalies: [],
        data_quality_warning_count: warningCount
      }
    }
  ];
}

const anomalies = [];

// 1. Lead volume falls more than 35% against 7-day average
const leadDropPercent = baseline.avg_unique_leads
  ? ((baseline.avg_unique_leads - current.unique_leads) / baseline.avg_unique_leads) * 100
  : 0;
if (leadDropPercent > 35) {
  anomalies.push({
    metric: 'unique_leads',
    issue: 'Lead volume dropped more than 35%',
    current: current.unique_leads,
    baseline: baseline.avg_unique_leads,
    change_percent: Number(leadDropPercent.toFixed(2))
  });
}

// 2. Cost per lead increases more than 30%
const costPerLeadIncreasePercent = baseline.avg_cost_per_lead
  ? ((current.cost_per_lead - baseline.avg_cost_per_lead) / baseline.avg_cost_per_lead) * 100
  : 0;
if (costPerLeadIncreasePercent > 30) {
  anomalies.push({
    metric: 'cost_per_lead',
    issue: 'Cost per lead increased more than 30%',
    current: current.cost_per_lead,
    baseline: baseline.avg_cost_per_lead,
    change_percent: Number(costPerLeadIncreasePercent.toFixed(2))
  });
}

// 3. Show rate falls by more than 15 percentage points
const showRateDropPoints = baseline.avg_show_rate - current.show_rate;
if (showRateDropPoints > 15) {
  anomalies.push({
    metric: 'show_rate',
    issue: 'Show rate fell more than 15 percentage points',
    current: current.show_rate,
    baseline: baseline.avg_show_rate,
    drop_points: Number(showRateDropPoints.toFixed(2))
  });
}

// 4. Speed to lead exceeds 10 minutes
if (current.speed_to_lead_minutes > 10) {
  anomalies.push({
    metric: 'speed_to_lead_minutes',
    issue: 'Speed to lead exceeds 10 minutes',
    current: current.speed_to_lead_minutes,
    threshold: 10
  });
}

// 5. Data quality warnings exceed five records
if (warningCount > 5) {
  anomalies.push({
    metric: 'data_quality_warning_count',
    issue: 'Data quality warnings exceed five records',
    current: warningCount,
    threshold: 5
  });
}

return [
  {
    json: {
      report_date: current.report_date,
      baseline_available: true,
      anomaly_detected: anomalies.length > 0,
      anomaly_status: anomalies.length > 0 ? 'anomaly_detected' : 'normal',
      anomaly_count: anomalies.length,
      anomalies: anomalies,
      data_quality_warning_count: warningCount
    }
  }
];

const allPages = $input.all();
let allContacts = [];

for (const page of allPages) {
  const contactsInPage = page.json.contacts || [];
  allContacts = allContacts.concat(contactsInPage);
}

const recordCount = allContacts.length;
const pageCount = allPages.length;

return [{
  json: {
    contacts: allContacts,
    page_count: pageCount,
    record_count: recordCount
  }
}];

const allPages = $input.all();
let allOpportunities = [];

for (const page of allPages) {
  const itemsInPage = page.json.opportunities || [];
  allOpportunities = allOpportunities.concat(itemsInPage);
}

const recordCount = allOpportunities.length;
const pageCount = allPages.length;

return [{
  json: {
    opportunities: allOpportunities,
    page_count: pageCount,
    record_count: recordCount
  }
}];

const allPages = $input.all();
let allAppointments = [];

for (const page of allPages) {
  const itemsInPage = page.json.events || [];
  allAppointments = allAppointments.concat(itemsInPage);
}

const recordCount = allAppointments.length;
const pageCount = allPages.length;

return [{
  json: {
    appointments: allAppointments,
    page_count: pageCount,
    record_count: recordCount
  }
}];

return [
  {
    json: {
      ad_spend: 1250.75,
      campaign_id: "campaign_test_001",
      campaign_name: "HVAC Emergency Repair - Test Campaign",
      clicks: 340,
      impressions: 15200,
      date: $('Set Reporting Window').item.json.report_date
    }
  }
];

const rows = $input.all();

if (rows.length === 0 || Object.keys(rows[0].json).length === 0) {
  return [
    {
      json: {
        baseline_available: false,
        historical_rows: 0,
        avg_unique_leads: 0,
        avg_appointments_booked: 0,
        avg_lead_to_appointment_rate: 0,
        avg_show_rate: 0,
        avg_close_rate: 0,
        avg_cost_per_lead: 0,
        avg_cost_per_appointment: 0,
        avg_revenue_per_lead: 0,
        avg_speed_to_lead_minutes: 0,
        avg_no_show_recovery_rate: 0
      }
    }
  ];
}

const data = rows.map(item => item.json);
const average = field =>
  data.reduce((sum, row) => sum + Number(row[field] || 0), 0) / data.length;

return [
  {
    json: {
      baseline_available: true,
      historical_rows: data.length,
      avg_unique_leads: average('unique_leads'),
      avg_appointments_booked: average('appointments_booked'),
      avg_lead_to_appointment_rate: average('lead_to_appointment_rate'),
      avg_show_rate: average('show_rate'),
      avg_close_rate: average('close_rate'),
      avg_cost_per_lead: average('cost_per_lead'),
      avg_cost_per_appointment: average('cost_per_appointment'),
      avg_revenue_per_lead: average('revenue_per_lead'),
      avg_speed_to_lead_minutes: average('speed_to_lead_minutes'),
      avg_no_show_recovery_rate: average('no_show_recovery_rate')
    }
  }
];
